import{_ as r,a0 as p,w as o,s as d,ao as l,I as e,x as i,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Arch Linux 中安装 MATE 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 中安装 MATE 桌面 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 中安装 MATE 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 中安装 MATE 桌面 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221106.1 ⭐️ How to Install MATE Desktop in Arch Linux [Complete Guide]","title":"如何在 Arch Linux 中安装 MATE 桌面","tag":"202302","desc":""},"relativePath":"202302/20221106.1 ⭐️ How to Install MATE Desktop in Arch Linux [Complete Guide].md","filePath":"[post].md"}'),h={name:"202302/20221106.1 ⭐️ How to Install MATE Desktop in Arch Linux [Complete Guide].md"};function u(g,t,m,A,k,T){const s=p("Link");return o(),d("div",null,[t[24]||(t[24]=l('<h1 id="如何在-arch-linux-中安装-mate-桌面" tabindex="-1">如何在 Arch Linux 中安装 MATE 桌面 <a class="header-anchor" href="#如何在-arch-linux-中安装-mate-桌面" aria-label="Permalink to “如何在 Arch Linux 中安装 MATE 桌面”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/21/104424o8p78qj8gp5hqghj.jpg" alt=""></p><blockquote><p>本指南将详细解释你在 Arch Linux 中安装 MATE 桌面所需的步骤。</p></blockquote><p>本指南分为两部分。第一部分讨论安装基础 Arch 系统。第二部分是在 Arch Linux 上安装完整的 MATE 桌面环境。</p><p>本文在以下版本中进行了测试：MATE 1.24 和 MATE 1.26。</p><h3 id="什么是-mate-桌面" tabindex="-1">什么是 MATE 桌面? <a class="header-anchor" href="#什么是-mate-桌面" aria-label="Permalink to “什么是 MATE 桌面?”">​</a></h3><p>当 GNOME 桌面从 GNOME 2 改变方向到 GNOME 3 时，改变了用户交互和界面，MATE 桌面仍然延续了“较旧的”或者说“传统的” GNOME 2 的开发方向。因此，MATE 桌面环境保留了 Linux 中的传统桌面体验。它速度快，内存消耗低。在我看来，MATE 桌面环境是一个被低估的桌面环境，需要更多的关注！</p>',7)),e("p",null,[t[1]||(t[1]=i("MATE 团队一直在继续开发，它是一个基于 GNOME 2 的流行桌面之一，但同时支持更新的技术。你可以在其 ",-1)),a(s,{href:"https://mate-desktop.org/"},{default:n(()=>[...t[0]||(t[0]=[i("官方网站",-1)])]),_:1}),t[2]||(t[2]=i(" 上了解更多信息。",-1))]),t[25]||(t[25]=e("h3",{id:"在-arch-linux-中安装-mate-桌面",tabindex:"-1"},[i("在 Arch Linux 中安装 MATE 桌面 "),e("a",{class:"header-anchor",href:"#在-arch-linux-中安装-mate-桌面","aria-label":"Permalink to “在 Arch Linux 中安装 MATE 桌面”"},"​")],-1)),t[26]||(t[26]=e("h4",{id:"第一部分-安装-arch-linux",tabindex:"-1"},[i("第一部分: 安装 Arch Linux "),e("a",{class:"header-anchor",href:"#第一部分-安装-arch-linux","aria-label":"Permalink to “第一部分: 安装 Arch Linux”"},"​")],-1)),t[27]||(t[27]=e("p",null,"如果你已经安装了 Arch Linux，则可以跳过此步骤，直接转到下面的 MATE 桌面安装部分。",-1)),e("p",null,[t[4]||(t[4]=i("要快速安装 Arch Linux，请按照这个自动化的 ",-1)),a(s,{href:"https://www.debugpoint.com/archinstall-guide/"},{default:n(()=>[...t[3]||(t[3]=[i("archinstall 指南",-1)])]),_:1}),t[5]||(t[5]=i(" 进行操作，该指南非常容易上手。安装完成后，继续至第二部分。",-1))]),t[28]||(t[28]=l('<h4 id="第二部分-在-arch-linux-中安装-mate-桌面" tabindex="-1">第二部分：在 Arch Linux 中安装 MATE 桌面 <a class="header-anchor" href="#第二部分-在-arch-linux-中安装-mate-桌面" aria-label="Permalink to “第二部分：在 Arch Linux 中安装 MATE 桌面”">​</a></h4><p>重新启动后，从 GRUB 中选择 Arch Linux。在 Arch Linux 提示符下，按顺序运行以下命令。这些命令将安装 Xorg 服务器、显示管理器、MATE 桌面组件、控制器包以及其他应用程序。</p><p>对于所有命令，请使用默认值，即在询问时按 Enter 键。</p><p>安装 Xorg。安装大小大约为 80 MB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed xorg</span></span></code></pre></div><p>安装显示管理器和 MATE 桌面组件。安装大小大约为 380 MB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed mate mate-extra ttf-freefont lightdm lightdm-gtk-greeter</span></span></code></pre></div>',7)),e("blockquote",null,[e("p",null,[t[7]||(t[7]=i("LCTT 译注：在 Arch Linux 中，很多时候 lightdm 显示管理器需要额外的配置才能正常启用。可以参考：",-1)),a(s,{href:"https://wiki.archlinux.org/title/LightDM"},{default:n(()=>[...t[6]||(t[6]=[i("LightDM - ArchWiki",-1)])]),_:1}),t[8]||(t[8]=i("。除此之外，可以安装 lightdm-gtk-greeter-settings 来对 lightdm-gtk-greeter 进行配置。",-1))])]),t[29]||(t[29]=l(`<p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/Installing-MATE-Packages.jpg" alt="安装 MATE 包"></p><p>安装应用软件：</p><p>这只是一个参考。你也可以安装你所需要的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed firefox vlc filezilla leafpad xscreensaver archlinux-wallpaper</span></span></code></pre></div><p>现在是时候以服务的方式启用显示管理器和网络管理器了。这样，下次登录时，它们就可以通过 systemd 自动运行了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl enable lightdm</span></span>
<span class="line"><span>systemctl enable NetworkManager</span></span></code></pre></div><p>使用重启命令重启系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p>如果一切顺利，你应该在 MATE 桌面上看到登录提示。</p><p>现在你可以使用刚刚创建的用户 ID 和密码登录。一个超快速和传统的 MATE 桌面将欢迎你的到来。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/MATE-Desktop-in-Arch-Linux-1.jpg" alt="Arch Linux 中的 MATE 桌面"></p><p>我希望本指南能帮助你从头开始创建自己的 Arch Linux 环境，并使用传统的 MATE 桌面。</p><hr>`,13)),e("p",null,[t[10]||(t[10]=i("via: ",-1)),a(s,{href:"https://www.debugpoint.com/mate-desktop-arch-linux-install/"},{default:n(()=>[...t[9]||(t[9]=[i("https://www.debugpoint.com/mate-desktop-arch-linux-install/",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=i("作者：",-1)),a(s,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...t[11]||(t[11]=[i("Arindam",-1)])]),_:1}),t[16]||(t[16]=i(" 选题：",-1)),a(s,{href:"https://github.com/lkxed"},{default:n(()=>[...t[12]||(t[12]=[i("lkxed",-1)])]),_:1}),t[17]||(t[17]=i(" 译者：",-1)),a(s,{href:"https://github.com/Chao-zhi"},{default:n(()=>[...t[13]||(t[13]=[i("Chao-zhi",-1)])]),_:1}),t[18]||(t[18]=i(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[14]||(t[14]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[21]||(t[21]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[19]||(t[19]=[i("LCTT",-1)])]),_:1}),t[22]||(t[22]=i(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:n(()=>[...t[20]||(t[20]=[i("Linux中国",-1)])]),_:1}),t[23]||(t[23]=i(" 荣誉推出",-1))])])}const M=r(h,[["render",u]]);export{f as __pageData,M as default};
